def _make_random_variable(distribution_cls):
    @interceptable
    @functools.wraps(distribution_cls, assigned=('__module__', '__name__'))
    @docstring_util.expand_docstring(cls=distribution_cls.__name__, doc=inspect.cleandoc(distribution_cls.__init__.__doc__ or ''))
    def func(*args, **kwargs):
        # pylint: disable=g-doc-args
        """Create a random variable for ${cls}.

        See ${cls} for more details.

        Returns:
          RandomVariable.

        #### Original Docstring for Distribution

        ${doc}
        """  # pylint: enable=g-doc-args
        sample_shape = kwargs.pop('sample_shape', ())
        value = kwargs.pop('value', None)
        return RandomVariable(distribution=distribution_cls(*args, **kwargs), sample_shape=sample_shape, value=value)
    return func
