def get_receiver(self, session=None, prefetch=0, mode=ReceiveSettleMode.PeekLock, idle_timeout=0, **kwargs):
    if self.entity and not self.requires_session and session:
        raise ValueError("A session cannot be used with a non-sessionful entity.")
    if self.entity and self.requires_session and not session:
        raise ValueError("This entity requires a session.")
    if int(prefetch) < 0 or int(prefetch) > 50000:
        raise ValueError("Prefetch must be an integer between 0 and 50000 inclusive.")
    prefetch += 1
    handler_id = str(uuid.uuid4())
    if session:
        return SessionReceiver(handler_id, self.entity_uri, self.auth_config, session=session, loop=self.loop, debug=self.debug, timeout=int(idle_timeout * 1000), prefetch=prefetch, mode=mode, **kwargs)
    else:
        return Receiver(handler_id, self.entity_uri, self.auth_config, loop=self.loop, debug=self.debug, timeout=int(idle_timeout * 1000), prefetch=prefetch, mode=mode, **kwargs)
