def convert_acquire(self, shift, instruction):
    meas_level = self._run_config.get('meas_level', 2)
    command_dict = {
        'name': 'acquire',
        't0': shift + instruction.start_time,
        'duration': instruction.duration,
        'qubits': [q.index for q in instruction.acquires],
        'memory_slot': [m.index for m in instruction.mem_slots]
    }

    if meas_level == 2:
        if instruction.command.discriminator:
            command_dict.update({
                'discriminators': [
                    QobjMeasurementOption(name=instruction.command.discriminator.name, params=instruction.command.discriminator.params)
                ]
            })
        if instruction.command.register_slot:
            command_dict.update({
                'register_slot': [regs.index for regs in instruction.reg_slots]
            })

    if meas_level >= 1:
        if instruction.command.kernel:
            command_dict.update({
                'kernels': [
                    QobjMeasurementOption(name=instruction.command.kernel.name, params=instruction.command.kernel.params)
                ]
            })

    return self._qobj_model(**command_dict)
