def _mkOp(fn):
    def op(*operands, key=None) -> RtlSignalBase:
        """
        :param operands: variadic parameter of input operands
        :param key: optional function applied on every operand
            before processing
        """
        assert operands, "operands cannot be empty"
        if key is not None:
            operands = map(key, operands)
        top = None
        for s in operands:
            if top is None:
                top = s
            else:
                top = fn(top, s)
        return top
    return op
